        }                                                          \
        else {                                                     \
            _buffer[_ii] = *(_type *)(_pi + _offset);              \
        }                                                          \
    }                                                              \
    _res = (_type)NI_Select(_buffer, 0, _filter_size - 1, _rank);  \
}                                                                  \
